"use client";

import * as React from "react";
type ThinkingSource = {
  label: string;
  icon?: React.ReactNode;
  href?: string;
  tooltip?: string;
};
type ThinkingStep =
  | { kind: "step"; label: string }
  | {
      kind: "search";
      label: string;
      activeLabel?: string;
      sources: ThinkingSource[];
      moreSources?: ThinkingSource[];
    };
interface ThinkingStateCleanProps {
  steps: ThinkingStep[];
  doneLabel?: string;
  stepMs?: number;
  loop?: boolean;
  onDone?: (seconds: number) => void;
  className?: string;
}
var ViewI = 160;
function ThinkingStateClean({
  steps: steps,
  doneLabel = `Finished thinking`,
  stepMs = 1300,
  loop = false,
  onDone: onDone,
  className: className,
}: ThinkingStateCleanProps) {
  let [p, m] = React.useState(0),
    [h, g] = React.useState(Math.min(1, steps.length)),
    [_, v] = React.useState(false),
    [y, b] = React.useState(0),
    [x, S] = React.useState<boolean>(true),
    [C, w] = React.useState(() => new Set()),
    T = React.useRef(0),
    E = React.useRef(false);
  (React.useEffect(() => {
    ((T.current = Date.now()),
      g(Math.min(1, steps.length)),
      v(false),
      b(0),
      S(true),
      w(new Set()));
    let t = [],
      n = 0;
    return (
      steps.forEach((e, r) => {
        (r > 0 && t.push(window.setTimeout(() => g(r + 1), n)),
          (n +=
            stepMs +
            (e.kind === `search` ? (e.sources.length + 1) * ViewI : 0)));
      }),
      t.push(
        window.setTimeout(() => {
          let e = Math.max(1, Math.round((Date.now() - T.current) / 1e3));
          (b(e), v(true), onDone?.(e));
        }, n),
      ),
      loop &&
        t.push(window.setTimeout(() => !E.current && m((e) => e + 1), n + 4e3)),
      () => t.forEach(clearTimeout)
    );
  }, [p, steps, stepMs, loop]),
    React.useEffect(() => {
      if (_) return;
      let e = window.setInterval(
        () => b(Math.floor((Date.now() - T.current) / 1e3)),
        250,
      );
      return () => clearInterval(e);
    }, [_, p]));
  let D = _ ? -1 : h - 1;
  return (
    <div
      className={[`ui-thinkc`, className].filter(Boolean).join(` `)}
      data-done={_ || void 0}
      key={p}
    >
      <style href={`ui-thinking-state-clean`} precedence={`default`}>
        {valueValue3}
      </style>
      <button
        type={`button`}
        className={`ui-thinkc__head`}
        aria-expanded={x}
        onClick={() => S((e) => !e)}
      >
        <span className={`ui-thinkc__mark`} aria-hidden={`true`}>
          {Array.from(
            {
              length: 9,
            },
            (e, t) => (
              <i
                style={{
                  animationDelay: `${valueValue[t]}ms`,
                }}
                key={t}
              />
            ),
          )}
        </span>
        <span className={`ui-thinkc__title`} key={_ ? `done` : `busy`}>
          {_ ? (
            `Worked for ${valueValue2(y)}`
          ) : (
            <>
              <span
                className={`ui-thinkc__shimmer`}
                data-text={`Thinking`}
              >{`Thinking`}</span>
              <span className={`ui-thinkc__time`}>{valueValue2(y)}</span>
            </>
          )}
        </span>
        <span className={`ui-thinkc__chevron`} aria-hidden={`true`}>
          <svg viewBox={`0 0 16 16`}>
            <path d={`M4.5 6.25 8 9.75l3.5-3.5`} />
          </svg>
        </span>
      </button>
      <div className={`ui-thinkc__body`} data-open={x}>
        <div className={`ui-thinkc__clip`}>
          <ol className={`ui-thinkc__list`} aria-live={`polite`}>
            {steps.slice(0, h).map((e, t) => {
              let n = t === D,
                a =
                  e.kind === `search` && n
                    ? (e.activeLabel ?? `Searching`)
                    : e.label;
              return (
                <li
                  className={`ui-thinkc__item`}
                  data-kind={e.kind}
                  data-active={n || void 0}
                  key={t}
                >
                  <span className={`ui-thinkc__node`} aria-hidden={`true`}>
                    {e.kind === `search` ? (
                      <svg viewBox={`0 0 24 24`} className={`ui-thinkc__globe`}>
                        <path d={`M22 12A10 10 0 1 0 12 22`} />
                        <path
                          d={`M20 5.7c-.93.07-2.13.43-2.96 1.5-1.5 1.94-3 2.1-4 1.46-1.5-.97-.24-2.54-2-3.4-1.15-.56-1.31-2.07-.67-3.26`}
                        />
                        <path
                          d={`M2 11c.76.66 1.83 1.27 3.09 1.27 2.6 0 3.12.5 3.12 2.48s0 1.99.52 3.48c.34.97.46 1.94-.22 2.77`}
                        />
                        <path
                          d={`m19.9 19.93 2.1 2.07m-.89-4.95a4.05 4.05 0 1 1-8.11 0 4.05 4.05 0 0 1 8.11 0Z`}
                        />
                      </svg>
                    ) : (
                      <span className={`ui-thinkc__dot`} />
                    )}
                  </span>
                  <div className={`ui-thinkc__content`}>
                    <span
                      className={
                        n
                          ? `ui-thinkc__label ui-thinkc__shimmer`
                          : `ui-thinkc__label`
                      }
                      data-text={a}
                    >
                      {a}
                    </span>
                    {e.kind === `search` && (
                      <div className={`ui-thinkc__sources`}>
                        {[
                          ...e.sources,
                          ...(C.has(t) ? (e.moreSources ?? []) : []),
                        ].map((t, n) => (
                          <Icono
                            source={t}
                            delay={
                              n < e.sources.length
                                ? 120 + n * ViewI
                                : (n - e.sources.length) * 70
                            }
                            key={t.label + n}
                          />
                        ))}
                        {e.moreSources?.length ? (
                          <button
                            type={`button`}
                            className={`ui-thinkc__source ui-thinkc__more`}
                            aria-expanded={C.has(t)}
                            style={{
                              animationDelay: `${120 + e.sources.length * ViewI}ms`,
                            }}
                            onClick={() => {
                              ((E.current = true),
                                w((e) => {
                                  let n = new Set(e);
                                  return (n.has(t) ? n.delete(t) : n.add(t), n);
                                }));
                            }}
                          >
                            {C.has(t)
                              ? `Show less`
                              : `+${e.moreSources.length} more`}
                          </button>
                        ) : null}
                      </div>
                    )}
                  </div>
                </li>
              );
            })}
            {_ && (
              <li className={`ui-thinkc__item`} data-kind={`done`}>
                <span className={`ui-thinkc__node`} aria-hidden={`true`}>
                  <svg viewBox={`0 0 16 16`} className={`ui-thinkc__check`}>
                    <circle cx={`8`} cy={`8`} r={`6.5`} />
                    <path d={`M5.4 8.3l1.75 1.75L10.7 6.4`} />
                  </svg>
                </span>
                <div className={`ui-thinkc__content`}>
                  <span className={`ui-thinkc__label`}>{doneLabel}</span>
                </div>
              </li>
            )}
          </ol>
        </div>
      </div>
    </div>
  );
}
function Icono({
  source: source,
  delay: delay,
}: {
  source: ThinkingSource;
  delay: number;
}) {
  let n = source.tooltip ?? source.href?.replace(/^https?:\/\//, ``),
    i = (
      <>
        {source.icon && (
          <span className={`ui-thinkc__favicon`}>{source.icon}</span>
        )}
        <span className={`ui-thinkc__source-label`}>{source.label}</span>
        {n && (
          <span className={`ui-thinkc__tip`} aria-hidden={`true`}>
            {n}
          </span>
        )}
      </>
    ),
    a = {
      className: `ui-thinkc__source`,
      "data-count": !source.icon || void 0,
      style: {
        animationDelay: `${delay}ms`,
      },
    };
  return source.href ? (
    <a {...a} href={source.href} target={`_blank`} rel={`noreferrer`}>
      {i}
    </a>
  ) : (
    <span {...a}>{i}</span>
  );
}
var valueValue = [0, 120, 240, 120, 240, 360, 240, 360, 480];
var valueValue2 = (e: number) =>
  e < 60
    ? `${e}s`
    : `${Math.floor(e / 60)}m ${String(e % 60).padStart(2, `0`)}s`;
var valueValue3 = `
/* Colors and motion as variables – override them on .ui-thinkc (see Theming in the docs) */
.ui-thinkc {
  --ui-tkc-card: #ffffff;
  --ui-tkc-ink: rgba(0, 0, 0, 0.88);
  --ui-tkc-strong: #000000;
  --ui-tkc-text: rgba(0, 0, 0, 0.61);
  --ui-tkc-muted: rgba(0, 0, 0, 0.45);
  --ui-tkc-faint: rgba(0, 0, 0, 0.27);
  --ui-tkc-icon: rgba(0, 0, 0, 0.447);
  --ui-tkc-line: rgba(0, 0, 0, 0.06);
  --ui-tkc-rail: rgba(0, 0, 0, 0.08);
  --ui-tkc-fill: rgba(0, 0, 0, 0.06);
  --ui-tkc-wash: rgba(0, 0, 0, 0.03);
  --ui-tkc-wash-big: rgba(0, 0, 0, 0.015);
  --ui-tkc-accent: rgba(0, 96, 226, 0.765);
  --ui-tkc-shine: rgba(255, 255, 255, 0.82);
  /* Strokes are shadows: a 0.5px hairline plus a soft lift */
  --ui-tkc-shadow: 0 0 0 0.5px rgba(0, 0, 0, 0.06), 0 1px 1px -1px rgba(0, 0, 0, 0.1), 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --ui-tkc-shadow-pop: 0 0 0 0.5px rgba(0, 0, 0, 0.08), 0 12px 28px -10px rgba(0, 0, 0, 0.16), 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --ui-tkc-ring: 0 0 0 0.5px rgba(0, 0, 0, 0.1);
  --ui-tkc-focus: rgba(0, 96, 226, 0.35);
  --ui-tkc-ease: cubic-bezier(0.22, 1, 0.36, 1);

  position: relative;
  box-sizing: border-box;
  container-type: inline-size;
  width: 100%;
  max-width: 440px;
  border-radius: 10px;
  background: var(--ui-tkc-card);
  box-shadow: var(--ui-tkc-shadow);
  font-family: "Inter", "InterVariable", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 13px;
  line-height: 20px;
  font-weight: 400;
  color: var(--ui-tkc-ink);
  -webkit-font-smoothing: antialiased;
}
.ui-thinkc *,
.ui-thinkc *::before,
.ui-thinkc *::after {
  box-sizing: border-box;
}
:where(.ui-thinkc) button { margin: 0; padding: 0; border: 0; background: none; font: inherit; color: inherit; cursor: pointer; }
:where(.ui-thinkc) svg { display: block; flex: none; }
.ui-thinkc button:focus-visible,
.ui-thinkc a:focus-visible {
  outline: 2px solid var(--ui-tkc-focus);
  outline-offset: 1px;
}

/* Header row: pixel mark + "Thinking 4s" / "Worked for 18s" + chevron */
.ui-thinkc__head {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  height: 44px;
  padding: 0 12px 0 16px;
  border-radius: 10px;
  text-align: left;
  transition: background-color 160ms ease, border-radius 0ms linear 360ms;
}
.ui-thinkc__head[aria-expanded="true"] {
  border-radius: 10px 10px 0 0;
  transition: background-color 160ms ease;
}
.ui-thinkc__head:hover {
  background: var(--ui-tkc-wash-big);
}
.ui-thinkc__mark {
  display: grid;
  grid-template-columns: repeat(3, 3px);
  grid-auto-rows: 3px;
  gap: 1.5px;
  place-content: center;
  width: 16px;
  height: 16px;
}
.ui-thinkc__mark i {
  border-radius: 0.75px;
  background: var(--ui-tkc-accent);
  animation: ui-thinkc-pixel 1.2s ease-in-out infinite both;
}
.ui-thinkc[data-done] .ui-thinkc__mark i {
  animation: ui-thinkc-settle 420ms var(--ui-tkc-ease) both;
}
.ui-thinkc__title {
  display: inline-flex;
  flex: 1;
  min-width: 0;
  gap: 8px;
  font-weight: 500;
  white-space: nowrap;
  color: var(--ui-tkc-ink);
  animation: ui-thinkc-in 420ms var(--ui-tkc-ease) both;
}
.ui-thinkc__title .ui-thinkc__shimmer {
  color: var(--ui-tkc-muted);
}
.ui-thinkc__time {
  font-weight: 400;
  font-variant-numeric: tabular-nums;
  color: var(--ui-tkc-faint);
}
.ui-thinkc__chevron {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  margin-right: -6px;
  border-radius: 6px;
  color: var(--ui-tkc-icon);
  transition: color 160ms ease;
}
.ui-thinkc__chevron svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.1;
  stroke-linecap: round;
  stroke-linejoin: round;
  transform: rotate(-90deg);
  transition: transform 260ms var(--ui-tkc-ease);
}
.ui-thinkc__head[aria-expanded="true"] .ui-thinkc__chevron svg {
  transform: none;
}
.ui-thinkc__head:hover .ui-thinkc__chevron {
  color: var(--ui-tkc-ink);
}

/* Body: folds away under a hairline – only this part animates and clips */
.ui-thinkc__body {
  display: grid;
  grid-template-rows: 1fr;
  border-top: 0.5px solid var(--ui-tkc-line);
  transition: grid-template-rows 360ms var(--ui-tkc-ease), opacity 260ms ease, border-color 260ms ease;
}
.ui-thinkc__body[data-open="false"] {
  grid-template-rows: 0fr;
  opacity: 0;
  border-top-color: transparent;
}
.ui-thinkc__clip {
  min-height: 0;
  /* clips only while folded, so tooltips can reach out when open */
  overflow: visible;
}
.ui-thinkc__body[data-open="false"] .ui-thinkc__clip {
  overflow: hidden;
}
.ui-thinkc__list {
  margin: 0;
  padding: 14px 16px 4px;
  list-style: none;
}

/* Timeline: icon column with a thin rail growing down to the next node */
.ui-thinkc__item {
  position: relative;
  display: grid;
  grid-template-columns: 16px minmax(0, 1fr);
  gap: 10px;
  padding-bottom: 12px;
  animation: ui-thinkc-in 520ms var(--ui-tkc-ease) both;
}
.ui-thinkc__item:not(:last-child)::before {
  content: "";
  position: absolute;
  left: 7.5px;
  top: 22px;
  bottom: 2px;
  width: 1px;
  background: var(--ui-tkc-rail);
  transform-origin: top;
  animation: ui-thinkc-line 520ms var(--ui-tkc-ease) both;
}
.ui-thinkc__node {
  display: grid;
  place-items: center;
  width: 16px;
  height: 20px;
}
.ui-thinkc__globe {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: var(--ui-tkc-icon);
  stroke-width: 1.6;
  stroke-linecap: round;
  stroke-linejoin: round;
}
/* A finished step is a small gray dot, the running one a blue pixel that pulses */
.ui-thinkc__dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--ui-tkc-faint);
  transition: background-color 300ms ease, border-radius 300ms ease;
}
.ui-thinkc__item[data-active] .ui-thinkc__dot {
  width: 6px;
  height: 6px;
  border-radius: 1.5px;
  background: var(--ui-tkc-accent);
  animation: ui-thinkc-pulse 1s ease-in-out infinite;
}
.ui-thinkc__check {
  width: 16px;
  height: 16px;
  animation: ui-thinkc-pop 460ms cubic-bezier(0.34, 1.56, 0.64, 1) both;
}
.ui-thinkc__check circle {
  fill: var(--ui-tkc-accent);
}
.ui-thinkc__check path {
  fill: none;
  stroke: #fff;
  stroke-width: 1.4;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 9;
  stroke-dashoffset: 9;
  animation: ui-thinkc-draw 360ms var(--ui-tkc-ease) 180ms forwards;
}

.ui-thinkc__content {
  min-width: 0;
}
.ui-thinkc__label {
  position: relative;
  display: inline-block;
  max-width: 100%;
  color: var(--ui-tkc-text);
  transition: color 300ms ease;
}
/* The running step: gray with a darker band sweeping through */
.ui-thinkc__item[data-active] .ui-thinkc__label {
  color: var(--ui-tkc-muted);
}
.ui-thinkc__item[data-kind="done"] .ui-thinkc__label {
  font-weight: 500;
  color: var(--ui-tkc-ink);
}

/* Sources: small white chips that pop in one after another */
.ui-thinkc__sources {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 8px;
  padding: 1px 0 2px;
}
.ui-thinkc__source {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  max-width: 100%;
  height: 26px;
  padding: 0 8px 0 6px;
  border-radius: 6px;
  background: var(--ui-tkc-card);
  box-shadow: var(--ui-tkc-shadow);
  font-size: 12px;
  line-height: 16px;
  color: var(--ui-tkc-ink);
  text-decoration: none;
  animation: ui-thinkc-chip 420ms var(--ui-tkc-ease) both;
}
a.ui-thinkc__source,
.ui-thinkc__more {
  position: relative;
  cursor: pointer;
  transition: background-color 160ms ease, color 160ms ease;
}
a.ui-thinkc__source:hover {
  background: var(--ui-tkc-wash);
}
/* "+3 more" – the quiet chip with an inner hairline */
.ui-thinkc .ui-thinkc__more {
  padding: 0 8px;
  background: none;
  box-shadow: inset 0 0 0 0.5px var(--ui-tkc-line);
  font-size: 12px;
  font-weight: 500;
  color: var(--ui-tkc-text);
}
.ui-thinkc .ui-thinkc__more:hover {
  background: var(--ui-tkc-wash);
  color: var(--ui-tkc-ink);
}
.ui-thinkc .ui-thinkc__more[aria-expanded="true"] {
  background: var(--ui-tkc-fill);
  color: var(--ui-tkc-ink);
}

/* Tooltip above the chip – a small white popover */
.ui-thinkc__tip {
  position: absolute;
  left: 50%;
  bottom: calc(100% + 6px);
  z-index: 2;
  padding: 4px 8px;
  border-radius: 6px;
  background: var(--ui-tkc-card);
  box-shadow: var(--ui-tkc-shadow-pop);
  color: var(--ui-tkc-text);
  font-size: 12px;
  line-height: 16px;
  white-space: nowrap;
  pointer-events: none;
  opacity: 0;
  transform: translate(-50%, 4px);
  transition: opacity 140ms ease, transform 200ms var(--ui-tkc-ease);
}
.ui-thinkc__source:hover .ui-thinkc__tip,
.ui-thinkc__source:focus-visible .ui-thinkc__tip {
  opacity: 1;
  transform: translate(-50%, 0);
  transition-delay: 250ms;
}

.ui-thinkc__source[data-count] {
  padding: 0 8px;
  background: none;
  box-shadow: inset 0 0 0 0.5px var(--ui-tkc-line);
  color: var(--ui-tkc-text);
}
.ui-thinkc__source-label {
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.ui-thinkc__favicon {
  display: grid;
  place-items: center;
  flex: none;
  width: 14px;
  height: 14px;
  border-radius: 4px;
  overflow: hidden;
  box-shadow: var(--ui-tkc-ring);
}
.ui-thinkc__favicon svg {
  width: 100%;
  height: 100%;
}

/* Shimmer over the working label – a darker band runs through the gray text */
.ui-thinkc__shimmer {
  position: relative;
}
.ui-thinkc__shimmer::after {
  content: attr(data-text);
  content: attr(data-text) / "";
  position: absolute;
  inset: 0;
  white-space: nowrap;
  color: transparent;
  background: linear-gradient(90deg, transparent 38%, var(--ui-tkc-shine) 50%, transparent 62%) 100% 0 / 300% 100%
    no-repeat;
  -webkit-background-clip: text;
  background-clip: text;
  animation: ui-thinkc-sweep 1.6s linear infinite;
  pointer-events: none;
}

@keyframes ui-thinkc-in {
  from { opacity: 0; transform: translateY(6px); filter: blur(3px); }
  to { opacity: 1; transform: none; filter: none; }
}
@keyframes ui-thinkc-line {
  from { transform: scaleY(0); }
  to { transform: scaleY(1); }
}
@keyframes ui-thinkc-chip {
  from { opacity: 0; transform: translateY(4px) scale(0.92); }
  to { opacity: 1; transform: none; }
}
@keyframes ui-thinkc-pulse {
  50% { transform: scale(0.7); opacity: 0.45; }
}
@keyframes ui-thinkc-pixel {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.2; }
}
@keyframes ui-thinkc-settle {
  from { opacity: 0.2; transform: scale(0.6); }
  to { opacity: 1; transform: none; }
}
@keyframes ui-thinkc-pop {
  0% { transform: scale(0.5); }
  60% { transform: scale(1.12); }
  100% { transform: scale(1); }
}
@keyframes ui-thinkc-draw {
  to { stroke-dashoffset: 0; }
}
@keyframes ui-thinkc-sweep {
  from { background-position: 100% 0; }
  to { background-position: 0% 0; }
}

/* Narrow (phones) */
@container (max-width: 360px) {
  .ui-thinkc__head { padding: 0 10px 0 14px; }
  .ui-thinkc__list { padding: 12px 14px 2px; }
}
/* Touch screens: bigger tap targets */
@media (pointer: coarse) {
  .ui-thinkc__head { height: 52px; }
  .ui-thinkc__source { height: 32px; }
}
@media (prefers-reduced-motion: reduce) {
  .ui-thinkc *,
  .ui-thinkc *::before,
  .ui-thinkc *::after {
    animation-duration: 1ms !important;
    animation-delay: 0ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 1ms !important;
  }
  .ui-thinkc__shimmer::after {
    display: none;
  }
  .ui-thinkc__check path {
    stroke-dashoffset: 0;
  }
}

/* Dark mode: follows a .dark class or data-theme="dark" on any ancestor, e.g. <html> */
:where(.dark, [data-theme="dark"]) .ui-thinkc {
  --ui-tkc-card: #1c1c1e;
